UPDATE wool_items SET
  name = #{name}, amount = #{amount}, wool_date = #{woolDate}, icon = #{icon}, image = #{image},
  images = #{images}, note = #{note}, record_type = #{recordType}, category = #{category},
  merchant = #{merchant}, payment_method = #{paymentMethod}, deposit_item_id = #{depositItemId},
  deposit_transaction_id = #{depositTransactionId}, created_at = #{createdAt}
WHERE id = #{id}

UPDATE wool_notes
title = #{title}, content = #{content}, updated_at = #{updatedAt},
WHERE id = #{id}
